KG42.register("source_edge_archive-c348b11325a57a61daad8a16",{"id":"15-multiagent_reverse_auction::v141-c-R006::E::v141-c-R006-E002","paper":"15-multiagent_reverse_auction","rule_id":"v141-c-R006","rule_ref":"15-multiagent_reverse_auction::v141-c-R006","record":{"edge_id":"v141-c-R006-E002","source":"coordination.price_signal","target":"bidding.supply","type":"conditional_on","constraint_ids":["v141-c-R006-C002"],"evidence_ids":["v141-b-g01-E16","v141-b-g01-E17"]},"evidence_class":"S","provenance_gate":"direct_C_edge_with_constraint_and_source_excerpt","scientific_acceptance":false,"accepted_constraint_ids":["v141-c-R006-C002"],"held_constraint_ids":[],"semantic_review_status":"supported","source":"COMP-97d6b21fedc8f7d3","target":"COMP-334f35169e6933ed","source_occurrence_id":"15-multiagent_reverse_auction::v141-c-R006::V::coordination.price_signal","target_occurrence_id":"15-multiagent_reverse_auction::v141-c-R006::V::bidding.supply","source_unit_id":"15-multiagent_reverse_auction::v141-a-M01::coordination.price_signal","target_unit_id":"15-multiagent_reverse_auction::v141-a-M01::bidding.supply","omega":{"market_type":"LEM","network_level":null,"jurisdiction":null,"pricing_scope":null,"time_scale":null,"participant_types":[],"trading_stage":"coordination","context_text":"Initial bid solicitation in the hour-ahead reverse auction for the grid-connected microgrid's lumped load. | Iterative bidding in the hour-ahead reverse auction for the grid-connected microgrid's lumped load.","unknown_fields":["network_level","jurisdiction","pricing_scope","time_scale","participant_types"],"evidence_ids":["v141-b-g01-E12","v141-b-g01-E16","v141-b-g01-E17"]},"active":true,"source_signature":"59d33cd7cf85751db81f070da9aee7e75af0d55a7bc3c443d33d5083298c51f7","relation_scope":"original_occurrence_pair_only","internal_to_parent":false,"source_science":{"mechanism_id":"v141-a-M01","source_definition":"The aggregator performs price-signal coordination by announcing the utility base price for the next hour's bid solicitation. Scope: Initial bid solicitation in the hour-ahead reverse auction for the grid-connected microgrid's lumped load. Price-signal updates are conditional on excess submitted supply: the aggregator lowers the price and requests new bids when supply exceeds demand. Scope: Iterative bidding in the hour-ahead reverse auction for the grid-connected microgrid's lumped load. Condition: Submitted supply exceeds demand.","target_definition":"Supply-bidding participation requires yellow-pages registration, which implements admission to this microgrid auction. Scope: Supply bidding by available generators in the microgrid's hour-ahead reverse auction. Condition: An available microgrid generator seeks to participate in bidding. The DER aggregator coordinates supply submission by soliciting bids from registered agents. Scope: Solicitation of next-hour DER supply bids in the microgrid reverse auction. Condition: Agents are registered in the yellow pages. The lowered auction-price signal coordinates renewed supply submissions: bidders that remain interested submit the new price, while others withdraw for that hour. Scope: Renewed supply bidding within a particular hourly microgrid auction. Condition: Submitted supply is higher than demand. The bidder submits a supply bid. Scope: Initial bid solicitation for available, registered microgrid generators in Algorithm 1. Condition: DER base price \u003c utility base price. Supply submission is withheld: the bidder drops and does not participate. Scope: Initial bid solicitation for available, registered microgrid generators in Algorithm 1. Condition: The DER base price is not less than the utility base price.","constraints":[{"constraint_id":"v141-c-R006-C002","kind":"logical","role":"core","statement":"Price-signal updates are conditional on excess submitted supply: the aggregator lowers the price and requests new bids when supply exceeds demand. Scope: Iterative bidding in the hour-ahead reverse auction for the grid-connected microgrid's lumped load. Condition: Submitted supply exceeds demand.","expression":null,"formalization_origin":"not_formalized","template_id":null,"members":["coordination.price_signal","bidding.supply"],"variable_refs":[],"parameter_refs":[],"evidence_ids":["v141-b-g01-E16","v141-b-g01-E17"]}],"evidence":[{"evidence_id":"v141-b-g01-E16","location":{"location_id":"src-1b3df4bc99-p04-c2r4__v141-a-M01-participation","page":4,"printed_page":null,"section":"IV. Proposed Methodology","anchor_text":"terminated. All available generators in the microgrid should 1) register to the yellow pages in orde","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-04.png","occurrence_role":"condition"},"source_text":"A reverse auction model has been implemented and realistically operated. Algorithm 1 briefly expresses the simplified pseudo code of the proposed reverse auction model. In Algorithm 1, the process is continuous unless the program is terminated. All available generators in the microgrid should register to the yellow pages in order to participate in bidding processes. The required amount of load is assumed to be correctly estimated for each upcoming hour; therefore the aggregator agent has this information ready to inform all agents registered to the yellow page. The main purpose of the aggregator agent is to purchase the required amount of energy with the least cost. The aggregator agent collects the submitted bids and checks whether the submitted supply matches the demand."},{"evidence_id":"v141-b-g01-E17","location":{"location_id":"src-1b3df4bc99-p04-c2r4__v141-a-M01-bidding","page":4,"printed_page":null,"section":"IV. Proposed Methodology","anchor_text":"terminated. All available generators in the microgrid should 1) register to the yellow pages in orde","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-04.png","occurrence_role":"condition"},"source_text":"If the supply is higher than the demand, the aggregator sends a new bidding request to the bidding agents by lowering the price. If bidding agents are still interested in the new submission, they submit the new price; otherwise they drop and quit from the auction for that particular hour. The process continues until only one qualified bidder remains in the auction."}],"omega":{"market_type":"LEM","network_level":null,"jurisdiction":null,"pricing_scope":null,"time_scale":null,"participant_types":[],"trading_stage":"coordination","context_text":"Initial bid solicitation in the hour-ahead reverse auction for the grid-connected microgrid's lumped load. | Iterative bidding in the hour-ahead reverse auction for the grid-connected microgrid's lumped load.","unknown_fields":["network_level","jurisdiction","pricing_scope","time_scale","participant_types"],"evidence_ids":["v141-b-g01-E12","v141-b-g01-E16","v141-b-g01-E17"]},"source_record":{"edge_id":"v141-c-R006-E002","source":"coordination.price_signal","target":"bidding.supply","type":"conditional_on","constraint_ids":["v141-c-R006-C002"],"evidence_ids":["v141-b-g01-E16","v141-b-g01-E17"]},"paper_scope_note":"Registration, auction invitation, bid, eligibility, and final power command are checked separately; the utility base price differs from the DER private base price; the general single-winner and two-winner cases are not combined into the same condition."}});
